#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

#define CHECK(call) do {                                           \
    cudaError_t err = (call);                                       \
    if (err != cudaSuccess) {                                       \
        std::fprintf(stderr, "%s: %s\n", #call,                     \
                     cudaGetErrorString(err));                      \
        std::exit(EXIT_FAILURE);                                   \
    }                                                              \
} while (0)

__global__ void sumValid(const float* input, float* output, int valid) {
    __shared__ float values[96];
    const unsigned tid = threadIdx.x;

    if (tid < static_cast<unsigned>(valid)) {
        values[tid] = input[tid];
    }

    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum += values[i];
        }
        output[0] = sum;
    }
}

// input must contain at least valid floats; output must hold one float.
// Both device allocations must remain alive until stream completion.
cudaError_t launchSum(const float* input, float* output,
                      int valid, cudaStream_t stream) {
    if (valid < 0 || valid > 96 || output == nullptr ||
        (valid > 0 && input == nullptr)) {
        return cudaErrorInvalidValue;
    }
    sumValid<<<1, 96, 0, stream>>>(input, output, valid);
    return cudaGetLastError();
}

int main() {
    float input[96];
    for (int i = 0; i < 96; ++i) {
        input[i] = static_cast<float>(i + 1);
    }

    float* deviceInput = nullptr;
    float* deviceOutput = nullptr;
    cudaStream_t stream;
    CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&deviceInput),
                     sizeof(input)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&deviceOutput),
                     sizeof(float)));
    CHECK(cudaMemcpy(deviceInput, input, sizeof(input),
                     cudaMemcpyHostToDevice));

    for (int valid = 0; valid <= 96; ++valid) {
        CHECK(launchSum(deviceInput, deviceOutput, valid, stream));
        CHECK(cudaStreamSynchronize(stream));

        float result = -1.0f;
        CHECK(cudaMemcpy(&result, deviceOutput, sizeof(result),
                         cudaMemcpyDeviceToHost));
        const float expected =
            static_cast<float>(valid * (valid + 1) / 2);
        if (result != expected) {
            std::fprintf(stderr, "Failed for valid=%d\n", valid);
            return EXIT_FAILURE;
        }
    }

    CHECK(cudaFree(deviceOutput));
    CHECK(cudaFree(deviceInput));
    CHECK(cudaStreamDestroy(stream));
    std::puts("All valid counts passed.");
    return EXIT_SUCCESS;
}
